import * as THREE from 'three/webgpu';
import { texture, uv, vec4, float, mix, vec3, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-pricing-card-2';

  const width = 2.2;
  const height = 2.75;

  const geometry = new THREE.PlaneGeometry(width, height, 1, 1);
  const material = new THREE.MeshStandardNodeMaterial();

  const colorInk = new THREE.Color('#16161d');
  const colorSurface = new THREE.Color('#0b0b10');
  const colorAccent = new THREE.Color('#ff2a38');

  const uvNode = uv();

  let baseColorNode;
  let mapTex = null;

  try {
    mapTex = ctx.textureLoader('/prism-assets/chrome/brushed-metal.map.png');
  } catch (e) {
    mapTex = null;
  }

  // engineered gradient: vertical mix from surface (bottom) to ink (top), with a thin accent
  // hairline near the top edge, plus subtle grain via a fract-based pseudo-noise from uv.
  const gradientT = uvNode.y;
  const gradientColor = mix(vec3(colorSurface.r, colorSurface.g, colorSurface.b), vec3(colorInk.r, colorInk.g, colorInk.b), gradientT);

  // subtle grain using a cheap hash from uv coordinates
  const grainSeed = uvNode.x.mul(1234.5).add(uvNode.y.mul(789.1));
  const grain = grainSeed.sin().mul(43758.5453).fract().sub(0.5).mul(0.03);

  const grainedColor = gradientColor.add(vec3(grain, grain, grain));

  // accent hairline near top (y > 0.94)
  const hairlineMask = uvNode.y.smoothstep(0.94, 0.965).sub(uvNode.y.smoothstep(0.965, 0.99));
  const accentVec = vec3(colorAccent.r, colorAccent.g, colorAccent.b);
  const withHairline = mix(grainedColor, accentVec, hairlineMask.clamp(0.0, 1.0));

  if (mapTex) {
    mapTex.wrapS = THREE.RepeatWrapping;
    mapTex.wrapT = THREE.RepeatWrapping;
    const mapNode = texture(mapTex, uvNode);
    baseColorNode = mix(withHairline, mapNode.rgb, float(0.35));
  } else {
    baseColorNode = withHairline;
  }

  material.colorNode = baseColorNode;
  material.metalnessNode = float(0.5);
  material.roughnessNode = float(0.55);
  material.clearcoatNode = float(0.2);
  material.clearcoatRoughnessNode = float(0.4);

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'hub-pricing-card-2-plane';
  group.add(mesh);

  group.position.set(0, -0.3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (mapTex && mapTex.dispose) {
      mapTex.dispose();
    }
  };

  return group;
}
